	String download_to_file;
	bool keep_partial_download = false;
	bool append_to_download_file = false;

	Ref<StreamPeerGZIP> decompressor;
	Ref<FileAccess> file;

	int body_len = -1;
	SafeNumeric<int> downloaded;
	SafeNumeric<int> final_body_size;
