void CanvasItem::queue_redraw()
{
    if (!is_inside_tree() || !canvas_item.is_valid()) {
        return;
    }
    Renderer::canvas_item_clear(canvas_item);
    if (is_visible_in_tree()) {
        drawing = true;
        notification(NOTIFICATION_DRAW);
        if (draw_callback) {
            draw_callback(this);
        }
        drawing = false;
    }
}

