Viewport::~Viewport()
{
	// Erase itself from viewport textures.
	for (ViewportTexture* E : viewport_textures) {
		E->vp = nullptr;
	}
	if (world_2d.is_valid()) {
		world_2d->remove_viewport(this);
	}
	ERR_FAIL_NULL(Renderer::data);
	Renderer::free_rid(viewport);
}

