String VideoStreamPlayer::get_bus() const
{
	for (int i = 0; i < AudioServer::get_bus_count(); i++) {
		if (AudioServer::get_bus_name(i) == bus) {
			return bus;
		}
	}
	return SceneString(Master);
}

