void RichTextLabel::Item::_clear_children()
{ // Only ever called on main or a paragraph (Line).
	while (subitems.size()) {
		Item* subitem = subitems.front()->get();
		memdelete(subitem);
		subitems.pop_front();
	}
}

RichTextLabel::Item::Item(ItemType p_type) : type(p_type)
{
	switch (p_type) {
	case ITEM_FRAME: {
		frame = memnew(FrameData);
	} break;
	case ITEM_DROPCAP: {
		dropcap = memnew(DropcapData);
	} break;
	case ITEM_IMAGE: {
		image = memnew(ImageData);
	} break;
	case ITEM_PARAGRAPH: {
		paragraph = memnew(ParagraphData);
	} break;
	case ITEM_TABLE: {
		table = memnew(TableData);
	} break;
	case ITEM_SHAKE:
	case ITEM_WAVE:
	case ITEM_TORNADO:
	case ITEM_RAINBOW:
	case ITEM_PULSE:
	case ITEM_CUSTOMFX: {
		fx = memnew(FXData(p_type));
	} break;
	case ITEM_FONT_SIZE: {
		font_size = 16;
	} break;
	case ITEM_LIST: {
		text = U"•";
	} break;
	default:
		break;
	}
}

RichTextLabel::Item::~Item()
{
	_clear_children();
	if (rid.is_valid()) {
		items.free(rid);
	}
	switch (type) {
	case ITEM_FRAME: {
		if (frame) {
			memdelete(frame);
		}
	} break;
	case ITEM_DROPCAP: {
		if (dropcap) {
			memdelete(dropcap);
		}
	} break;
	case ITEM_IMAGE: {
		if (image) {
			memdelete(image);
		}
	} break;
	case ITEM_PARAGRAPH: {
		if (paragraph) {
			memdelete(paragraph);
		}
	} break;
	case ITEM_TABLE: {
		if (table) {
			memdelete(table);
		}
	} break;
	case ITEM_SHAKE:
	case ITEM_WAVE:
	case ITEM_TORNADO:
	case ITEM_RAINBOW:
	case ITEM_PULSE:
	case ITEM_CUSTOMFX: {
		if (fx) {
			memdelete(fx);
		}
	} break;
	default:
		break;
	}
}

